package com.haucheng.erp.controller;
import com.haucheng.erp.auth.RequirePermission; import com.haucheng.erp.common.ApiResponse; import com.haucheng.erp.dto.UnitRequest; import com.haucheng.erp.entity.MdUnit; import com.haucheng.erp.service.UnitService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/master-data/units") @RequiredArgsConstructor public class UnitController { private final UnitService service;
 @GetMapping @RequirePermission("system.unit.view") public ApiResponse<List<MdUnit>> list(){return ApiResponse.success(service.getAll());} @GetMapping("/options") @RequirePermission("system.product.view") public ApiResponse<List<MdUnit>> options(){return ApiResponse.success(service.getOptions());}
 @GetMapping("/{id}") @RequirePermission("system.unit.view") public ApiResponse<MdUnit> get(@PathVariable Long id){return ApiResponse.success(service.getById(id));} @PostMapping @RequirePermission("system.unit.create") public ApiResponse<MdUnit> create(@Valid @RequestBody UnitRequest r){return ApiResponse.success(service.create(r));} @PutMapping("/{id}") @RequirePermission("system.unit.update") public ApiResponse<MdUnit> update(@PathVariable Long id,@Valid @RequestBody UnitRequest r){return ApiResponse.success(service.update(id,r));}
 @PostMapping("/{id}/enable") @RequirePermission("system.unit.disable") public ApiResponse<Void> enable(@PathVariable Long id){service.updateStatus(id,true);return ApiResponse.success();} @PostMapping("/{id}/disable") @RequirePermission("system.unit.disable") public ApiResponse<Void> disable(@PathVariable Long id){service.updateStatus(id,false);return ApiResponse.success();} @DeleteMapping("/{id}") @RequirePermission("system.unit.delete") public ApiResponse<Void> delete(@PathVariable Long id){service.delete(id);return ApiResponse.success();}
}
